import React from 'react';

const Home = () => {
  return (
    <div>
      <h1>MMD Anaalytics India Private Limited</h1>
      <p>
        Professional Financial Solutions & Trading Services<br></br>Trusted partner for financial services, business consulting, broking solutions and coal trading based in Ranchi, Jharkhand.
 </p>

      <h2>Our Core Values</h2>
      <ul>
        <li>Integrity in financial reporting</li>
        <li>Excellence in coal transport</li>
        <li>Customer-first broking</li>
      </ul>
    </div>
  );
};

export default Home;
